function toHex2(n){ var s=Number(n).toString(16); return s.length<2?('0'+s):s; }
function parseHexColor(s){
  var t=String(s||'').trim(), m;
  if((m=/^#?([0-9a-fA-F]{6})$/.exec(t))) return {r:parseInt(m[1].slice(0,2),16), g:parseInt(m[1].slice(2,4),16), b:parseInt(m[1].slice(4,6),16)};
  if((m=/^#?([0-9a-fA-F]{3})$/.exec(t))) return {r:parseInt(m[1][0]+m[1][0],16), g:parseInt(m[1][1]+m[1][1],16), b:parseInt(m[1][2]+m[1][2],16)};
  return null;
}
function withAlpha(hex, a){
  var c=parseHexColor(hex); if(!c) return {ok:false, reason:'bad hex color'};
  a=Number(a); if(!(a>=0 && a<=1)) return {ok:false, reason:'alpha must be 0-1'};
  return {ok:true, rgba:'rgba('+c.r+', '+c.g+', '+c.b+', '+a+')',
          hex8:'#'+toHex2(c.r)+toHex2(c.g)+toHex2(c.b)+toHex2(Math.round(a*255))};
}

var EXPORTS={parseHexColor:parseHexColor,withAlpha:withAlpha};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.OpacityForgePure = EXPORTS; }
